Q: What is the equivalent Cmd.exe program for this PowerShell one-liner program? A: <p>You can invoke a line of powershell from cmd. I do this often. You just have to manage the quoting. Cmd only knows double quotes, and the pipe has to be escaped with the rest within double quotes.</p>
<pre><code>powershell &quot;Get-ChildItem -Path E:\input\* -Include *.xml | foreach { $html='E:\output\'+$_.basename+'.html'; .\program $_.fullname $html}&quot;
</code></pre>

Q: Best way to update a clock every second in Linux A: <p>Using the <code>signal</code>, <code>alarm</code>, <code>time</code> and <code>ctime_r</code> functions in C is the easiest way.</p>
<p>The following code raises <code>SIGALRM</code> every second in <code>sys_init</code> calling <code>sys_sigalrm</code> getting the accumulated frames and fetching the time converted to string. This implementation explicitly avoids using <code>clock_gettime</code> for frametime and just uses the per seconds alarm signal tick.
The main loop just increments frame count until <code>KEY_ESC</code> is pressed or <code>SIGINT</code>,<code>SIGTERM</code> or <code>SIGHUP</code> is raised.</p>
<p><strong>sys.h</strong></p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdlib.h&gt;
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;
#include &lt;stddef.h&gt;
#include &lt;math.h&gt;
#include &lt;string.h&gt;
#include &quot;term.h&quot;

typedef void  (*FUNC_PTR_SIGNAL)(int sig);
typedef bool  (*FUNC_PTR_INIT)  (void   );
typedef void  (*FUNC_PTR_HALT)  (void   );
typedef bool  (*FUNC_PTR_STEP)  (void   );
typedef bool  (*FUNC_PTR_PRINT) (void   );
typedef char* (*FUNC_PTR_FPS)   (void   );

static inline bool  sys_init();
static inline void  sys_halt();
static inline void  sys_sigalrm(int sig);
static inline void  sys_sigint(int sig);
static inline char* sys_time();
static inline char* sys_fps();
static inline bool  sys_step();
static inline bool  sys_print();

struct
{
        FUNC_PTR_SIGNAL        interrupt;
        FUNC_PTR_SIGNAL        alarm;
        FUNC_PTR_INIT          init;
        FUNC_PTR_HALT          halt;
        FUNC_PTR_STEP          step;
        FUNC_PTR_PRINT         print;
        FUNC_PTR_FPS           fps;
        struct
        {
                uint64_t     cnt;
                size_t       acc;
                size_t       fps;
                char cnt_str[32];
                char acc_str[32];
                char fps_str[32];
        } frame;
        struct
        {
                time_t       beg;
                time_t       now;
                size_t       sec;
                char     str[32];
                char     sec_str[32];
        } time;
} sys = { .interrupt = sys_sigint, .alarm = sys_sigalrm, .init = sys_init, .halt = sys_halt, .step = sys_step, .print = sys_print, .fps = sys_fps, .frame.acc = 0, .frame.cnt = 0, .frame.fps = 0, .frame.fps_str = &quot;&quot;, .frame.cnt_str = &quot;&quot;, .frame.acc_str = &quot;&quot;, .time.now = 0, .time.beg = 0, .time.sec = 0, .time.str = &quot;&quot; };

static inline bool sys_print()
{
                static bool first = true;
                if(first)
                {
                        printf(&quot; %16s   %16s   %16s   %16s  %s&quot;, &quot;uptime&quot;, &quot;frames total&quot;, &quot;frames sec&quot;, &quot;fps&quot;, &quot;calendar time&quot;);
                        puts(&quot;&quot;);
                        first = false;
                }
                printf(&quot;\r[%16s] [%16s] [%16s] [%16s] %s&quot;,
                sys.time.sec_str,
                sys.frame.fps == 0 ? sys.frame.acc_str : sys.frame.cnt_str,
                sys.frame.acc_str,
                sys.frame.fps == 0 ? sys.frame.acc_str : sys.frame.fps_str,
                sys.time.str);
                return true;
}

static inline bool sys_step()
{
        sys.frame.acc++;
        snprintf(sys.frame.acc_str, 31, &quot;%16zu&quot;, sys.frame.acc);
        return true;
}

static inline char* sys_fps()
{
        sys.frame.cnt += sys.frame.acc;
        sys.frame.fps = sys.frame.acc;
        sys.frame.acc = 0;

        snprintf(sys.frame.fps_str, 31, &quot;%16zu&quot;, sys.frame.fps);
        snprintf(sys.frame.cnt_str, 31, &quot;%16zu&quot;, sys.frame.cnt);
        return sys.frame.fps_str;
}

static inline char* sys_time()
{
        static bool first = true;
        sys.time.now = time(NULL);
        if(first)
        {
                sys.time.beg = sys.time.now; sys.time.sec = 0; first = false;
        }
        else
        {
                sys.time.sec++;
        }
        ctime_r(&amp;sys.time.now, sys.time.str);
        sys.time.str[strlen(sys.time.str) - 1] = '\0';
        snprintf(sys.time.sec_str, 31, &quot;%16zu&quot;, sys.time.sec);
        return sys.time.str;
}

static inline bool sys_init()
{
        sys_time();
        atexit(sys.halt);
        signal(SIGINT, sys.interrupt);
        signal(SIGTERM, sys.interrupt);
        signal(SIGHUP, sys.interrupt);
        signal(SIGALRM,sys.alarm);
        alarm(1);

        term_init();

        return true;
}

static inline void sys_sigalrm(int sig)
{
        alarm(1);
        sys_fps();
        sys_time();
}

static inline void sys_sigint(int sig)
{
        exit(EXIT_FAILURE);
}

static inline void sys_halt()
{
        term_halt();
        puts(&quot;&quot;);
}
</code></pre>
<p><strong>cfps.c</strong></p>
<pre class="lang-c prettyprint-override"><code>#include &quot;sys.h&quot;

int main(int argc, char** argv)
{
    if(!sys.init()) exit(EXIT_FAILURE);

    while(term_getc() != KEY_ESC &amp;&amp; sys.step() &amp;&amp; sys.print());

    exit(EXIT_SUCCESS);
}
</code></pre>
<pre class="lang-bash prettyprint-override"><code>           uptime       frames total         frames sec                fps  calendar time
[             101] [        98905046] [          407272] [         1010861] Tue Aug  4 15:04:53 2026
</code></pre>
<p><strong>term.h</strong></p>
<pre class="lang-c prettyprint-override"><code>#pragma once

#include &lt;errno.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;sys/param.h&gt;
#include &lt;unistd.h&gt;
#include &lt;termios.h&gt;
#include &lt;time.h&gt;

#ifndef STDIN_FILENO
#define STDIN_FILENO 0
#endif

#ifndef KEY_ESC
#define KEY_ESC 27
#endif

void  term_halt()
{
        struct termios info;
        int flags = fcntl(STDIN_FILENO,F_GETFL,0);
        fcntl(STDIN_FILENO, F_SETFL,flags &amp; ~O_NONBLOCK);
        tcgetattr(STDIN_FILENO, &amp;info);
        info.c_lflag |= ICANON;
        info.c_lflag |= ECHO;
        tcsetattr(STDIN_FILENO, TCSANOW, &amp;info);
}

bool term_init()
{
        struct termios info;
        tcgetattr(STDIN_FILENO, &amp;info);
        info.c_lflag &amp;= ~ICANON;
        info.c_lflag &amp;= ~ECHO;
        info.c_cc[VMIN] = 1;
        info.c_cc[VTIME] = 0;
        tcsetattr(STDIN_FILENO, TCSANOW, &amp;info);
        int flags = fcntl(STDIN_FILENO,F_GETFL,0);
        if (flags == -1)
        {
                perror(&quot;fcntl: F_GETFL failed&quot;);
                term_halt();
                return false;
        }
        if(fcntl(STDIN_FILENO, F_SETFL,flags | O_NONBLOCK) == -1)
        {
                perror(&quot;fcntl: F_SETFL failed&quot;);
                term_halt();
                return false;
        }

        return true;
}

int term_getc()
{
        int c = '\0';
        /* use read here because of slow performance getc and fgetc */
        if(read(STDIN_FILENO, &amp;c, 1) == 1)
                return c;

        if(errno == EAGAIN || errno == EWOULDBLOCK)
                return c;

        perror(&quot;getc: read failed\n&quot;);
        exit(EXIT_FAILURE);
}
</code></pre>

